css:
@font-face {
  font-family: "TH Sarabun Document";
  src: url("/assets/connect_diagnostics_core/fonts/THSarabun.ttf") format("truetype");
  font-style: normal;
  font-weight: 400;
}

@page {
  size: A4 portrait;
  margin: 0;
}

.print-format {
  width: 210mm !important;
  min-height: 297mm !important;
  margin: 0 !important;
  padding: 0 !important;
}

.cd-sales-order, .cd-sales-order * { box-sizing: border-box; }
.cd-sales-order { position: relative; width: 210mm; height: 297mm; overflow: hidden; color: #303030; background: #fff; font-family: "TH Sarabun Document", sans-serif; font-size: 3.8mm; line-height: 1.05; }
.cd-sales-order .document-header { position: relative; height: 52mm; }
.cd-sales-order .company-logo { position: absolute; top: 14mm; left: 12mm; width: 20mm; height: 9mm; object-fit: contain; }
.cd-sales-order .company-info { position: absolute; top: 12mm; left: 34mm; width: 110mm; }
.cd-sales-order .company-info strong { display: block; font-size: 5.5mm; font-weight: 400; }
.cd-sales-order .company-info span { display: block; margin-top: 2mm; font-size: 3.8mm; }
.cd-sales-order h1 { position: absolute; top: 30mm; right: 26mm; margin: 0; font-size: 6mm; font-weight: 400; }
.cd-sales-order .tax-info { position: absolute; top: 44mm; left: 14mm; }
.cd-sales-order .order-info { display: grid; grid-template-columns: 46% 54%; width: 182mm; height: 54mm; margin: 0 14mm; }
.cd-sales-order .customer-panel, .cd-sales-order .document-panel { position: relative; padding: 3mm; }
.cd-sales-order .customer-code { position: absolute; top: 3mm; left: 20mm; }
.cd-sales-order .customer-name { margin: 4mm 0 0 0; font-weight: 700; }
.cd-sales-order .customer-address { width: 80mm; height: 22mm; overflow: hidden; }
.cd-sales-order .reference, .cd-sales-order .delivery-by { position: absolute; left: 3mm; right: 0; }
.cd-sales-order .reference { bottom: 8mm; } .cd-sales-order .delivery-by { bottom: 1mm; }
.cd-sales-order .reference span, .cd-sales-order .delivery-by span { display: inline-block; width: 21mm; }
.cd-sales-order .document-panel dl { display: grid; grid-template-columns: 38mm 1fr; row-gap: 4.5mm; margin: 0; }
.cd-sales-order .document-panel dt, .cd-sales-order .document-panel dd { margin: 0; }
.cd-sales-order .items-section { width: 182mm; height: 111mm; margin: 0 14mm; }
.cd-sales-order table { width: 100%; height: 100%; border-collapse: separate; border-spacing: 0; table-layout: fixed; border: 0.25mm solid #333; border-radius: 2.5mm; overflow: hidden; }
.cd-sales-order th, .cd-sales-order td { padding: 1.4mm; border-right: 0.25mm solid #333; }
.cd-sales-order th:last-child, .cd-sales-order td:last-child { border-right: 0; }
.cd-sales-order th { height: 8mm; border-bottom: 0.25mm solid #333; font-weight: 400; text-align: center; }
.cd-sales-order td { vertical-align: top; }
.cd-sales-order td:nth-child(1), .cd-sales-order td:nth-child(3), .cd-sales-order td:nth-child(6) { text-align: center; }
.cd-sales-order td:nth-child(4), .cd-sales-order td:nth-child(5) { text-align: right; }
.cd-sales-order col.no { width: 6.5%; } .cd-sales-order col.description { width: 39.5%; } .cd-sales-order col.quantity { width: 16.5%; } .cd-sales-order col.rate { width: 12%; } .cd-sales-order col.amount { width: 13%; } .cd-sales-order col.shelf { width: 12.5%; }
.cd-sales-order .summary-section { display: grid; grid-template-columns: 46% 54%; width: 182mm; height: 34mm; margin: 2mm 14mm 0; }
.cd-sales-order .remarks { position: relative; padding: 0 3mm; }
.cd-sales-order .amount-words { position: absolute; left: 0; right: 0; bottom: 0; }
.cd-sales-order .totals { display: grid; grid-template-columns: 55mm 1fr; row-gap: 1.4mm; margin: 0; }
.cd-sales-order .totals dt, .cd-sales-order .totals dd { margin: 0; }
.cd-sales-order .totals dd { text-align: right; }
.cd-sales-order .approval-section { position: relative; display: grid; grid-template-columns: repeat(3, 1fr); align-items: end; width: 182mm; height: 38mm; margin: 0 14mm; padding-bottom: 4mm; }
.cd-sales-order .company-signature { position: absolute; top: 0; left: 0; width: 100%; text-align: center; }
.cd-sales-order .signature { text-align: center; }
.cd-sales-order .signature span { display: block; width: 30mm; margin: 0 auto 6mm; border-bottom: 0.2mm solid #555; }
